import math

def is_power_of_two(num):
    if num <= 0:
        return False
    return (num & (num - 1) == 0)

cases = [1, 2, 3, 4, 5]
results = {}

for k in cases:
    target = 5**k + 3

    if is_power_of_two(target):
        # If it is a power of two, find n
        n = round(math.log2(target))
        # Check if n is an integer (should be if is_power_of_two is correct)
        if 2**n == target:
            # Check constraints
            if n >= 3:
                results[k] = n
            else:
                results[k] = "n < 3"
        else:
            results[k] = "not a power of 2"
    else:
        results[k] = "not a power of 2"

print("Results for k=1 to k=5:")
for k, result in results.items():
    print(f"k={k}: {result}")

def is_power_of_5(n):
    if n <= 0:
        return False
    while n % 5 == 0:
        n //= 5
    return n == 1

solutions = []
for n in range(3, 100):
    val = 2**n - 3
    if is_power_of_5(val):
        solutions.append(n)
print(solutions)

